scripts.host.probe:
{
  "schema": 1,
  "timeout_ms": 360000,
  "steps": [
    {
      "op": "wait",
      "editing": true
    },
    {
      "op": "assert_relay"
    },
    {
      "op": "editor_pick",
      "input_player": 0
    },
    {
      "op": "editor_move",
      "input_player": 0,
      "x_fraction": 0.35
    },
    {
      "op": "wait",
      "renders": 5,
      "elapsed_ms": 1000
    },
    {
      "op": "menu",
      "command": "video_mark valid-preview-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200
    },
    {
      "op": "screenshot_pair",
      "name": "valid-preview-host"
    },
    {
      "op": "assert_editor",
      "input_player": 0,
      "screen_text_contains": "Valid spot - click to INSTALL your brain"
    },
    {
      "op": "assert_control",
      "control": "LabelNetMatchStatus",
      "text_contains": "0 of 2",
      "fits": true,
      "inside": "BoxNetMatchStatus"
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": true
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": false
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "setup_ready": 1
    },
    {
      "op": "menu",
      "command": "video_mark placed-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200
    },
    {
      "op": "screenshot_pair",
      "name": "placed-host"
    },
    {
      "op": "assert_editor",
      "input_player": 0,
      "equals": {
        "ready": true,
        "submitted": true
      }
    },
    {
      "op": "assert_control",
      "control": "LabelNetMatchStatus",
      "text_contains": "1 of 2",
      "fits": true,
      "inside": "BoxNetMatchStatus"
    },
    {
      "op": "key_down",
      "key": "Return"
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "key_up",
      "key": "Return"
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "editing": false,
      "paused": false
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "equals": {
        "alive": true,
        "brain_count": 2
      }
    },
    {
      "op": "menu",
      "command": "video_mark playing-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200
    },
    {
      "op": "screenshot_pair",
      "name": "playing-host"
    },
    {
      "op": "game_mouse",
      "button": "right",
      "down": true
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "pie_point",
      "input_player": 0,
      "command": 6
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "menu",
      "command": "video_mark pie-buy-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200
    },
    {
      "op": "screenshot_pair",
      "name": "pie-buy-host"
    },
    {
      "op": "assert_pie",
      "input_player": 0,
      "equals": {
        "visible": true,
        "description": "Buy Menu - click to open"
      }
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": true
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": false
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "game_mouse",
      "button": "right",
      "down": false
    },
    {
      "op": "wait",
      "renders": 5,
      "elapsed_ms": 1200
    },
    {
      "op": "menu",
      "command": "video_mark shop-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200
    },
    {
      "op": "screenshot_pair",
      "name": "shop-host"
    },
    {
      "op": "assert_buy",
      "input_player": 0,
      "equals": {
        "visible": true,
        "enabled": true,
        "buy_allowed": true
      }
    },
    {
      "op": "menu",
      "command": "activate OrderClearButton",
      "scope": "buy",
      "input_player": 0
    },
    {
      "op": "menu",
      "command": "activate CraftTab",
      "scope": "buy",
      "input_player": 0
    },
    {
      "op": "shop_pick",
      "input_player": 0,
      "preset": "Base.rte/Rocket MK2"
    },
    {
      "op": "menu",
      "command": "activate BodiesTab",
      "scope": "buy",
      "input_player": 0
    },
    {
      "op": "shop_pick",
      "input_player": 0,
      "preset": "Coalition.rte/Soldier Light"
    },
    {
      "op": "menu",
      "command": "activate GunsTab",
      "scope": "buy",
      "input_player": 0
    },
    {
      "op": "shop_pick",
      "input_player": 0,
      "preset": "Coalition.rte/Assault Rifle"
    },
    {
      "op": "menu",
      "command": "video_mark order-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200
    },
    {
      "op": "screenshot_pair",
      "name": "order-host"
    },
    {
      "op": "assert_buy",
      "input_player": 0,
      "equals": {
        "cart": [
          "Coalition.rte/Soldier Light",
          "Coalition.rte/Assault Rifle"
        ],
        "craft": "Base.rte/Rocket MK2",
        "passengers": 1
      },
      "remember": "order"
    },
    {
      "op": "assert_control",
      "scope": "buy",
      "input_player": 0,
      "control": "BuyButton",
      "equals": {
        "visible": true,
        "enabled": true
      },
      "fits": true,
      "inside": "BuyGUIBox"
    },
    {
      "op": "menu",
      "command": "activate BuyButton",
      "scope": "buy",
      "input_player": 0
    },
    {
      "op": "wait_scene",
      "input_player": 0,
      "funds_delta_from": "order"
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "funds_delta_from": "order"
    },
    {
      "op": "wait_scene",
      "input_player": 0,
      "delivered": "Coalition.rte/Soldier Light"
    },
    {
      "op": "menu",
      "command": "video_mark arrival-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200
    },
    {
      "op": "screenshot_pair",
      "name": "arrival-host"
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "delivered": "Coalition.rte/Soldier Light",
      "equals": {
        "alive": true
      }
    },
    {
      "op": "key_down",
      "key": "E"
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "key_up",
      "key": "E"
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait_scene",
      "input_player": 0,
      "equals": {
        "preset": "Coalition.rte/Soldier Light",
        "weapon": "Coalition.rte/Assault Rifle"
      }
    },
    {
      "op": "game_mouse",
      "down": true
    },
    {
      "op": "wait",
      "renders": 5,
      "sim_advanced": 12
    },
    {
      "op": "menu",
      "command": "video_mark fire-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200
    },
    {
      "op": "screenshot_pair",
      "name": "fire-host"
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "equals": {
        "alive": true,
        "fired": true,
        "weapon": "Coalition.rte/Assault Rifle"
      }
    },
    {
      "op": "game_mouse",
      "down": false
    },
    {
      "op": "assert_relay"
    },
    {
      "op": "finish"
    }
  ],
  "activate_phase": "Running",
  "sim_clock": "lockstep"
}

